#requires -Version 5.1
[CmdletBinding()]
param([switch]$ResumeIncomplete, [switch]$CheckOnly, [string]$PreviewPath = '')
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Windows.Forms, System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()
$admin = (New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $admin -and -not $CheckOnly -and -not $PreviewPath) {
    try { Start-Process -FilePath "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe" -Verb RunAs -WindowStyle Normal -ArgumentList ('-NoProfile -STA -ExecutionPolicy Bypass -File "' + $PSCommandPath + '"' + $(if($ResumeIncomplete){' -ResumeIncomplete'}else{''})) }
    catch { [System.Windows.Forms.MessageBox]::Show('Autorizzazione amministratore annullata. Nessun programma installato.','M3PRO Setup') | Out-Null }
    exit
}
$engineBase64 = ''
$engineHash = 'a271d187e6d820db1b208648f930b1eee483a5a7d7db1beebb4924637b23ead3'
$jobRoot = Join-Path $env:TEMP ('M3PRO-Setup-GUI-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $jobRoot | Out-Null
$engine = Join-Path $jobRoot 'INSTALLA-MEFF.ps1'
[IO.File]::WriteAllBytes($engine, [Convert]::FromBase64String($engineBase64))
if ((Get-FileHash $engine -Algorithm SHA256).Hash -ne $engineHash) { throw 'Il motore di installazione non supera il controllo integrita.' }
$script:worker = $null
$script:mode = ''
$script:lastLog = ''
$script:sequence = 0
$script:machinePresent = $false
$script:readyForInstall = $false
$script:stdout = ''
$script:stderr = ''
$statusFile = Join-Path $jobRoot 'checklist.json'
$dark=[Drawing.ColorTranslator]::FromHtml('#102333')
$panelColor=[Drawing.ColorTranslator]::FromHtml('#183449')
$teal=[Drawing.ColorTranslator]::FromHtml('#20CEC5')
$muted=[Drawing.ColorTranslator]::FromHtml('#B9CDD9')
$form = New-Object Windows.Forms.Form
$form.Text='M3PRO | Installazione prodotto'
$form.ClientSize=New-Object Drawing.Size(940,720)
$form.StartPosition='CenterScreen'
$form.FormBorderStyle='FixedDialog'
$form.MaximizeBox=$false
$form.BackColor=$dark
$form.ForeColor=[Drawing.Color]::White
$form.Font=New-Object Drawing.Font('Segoe UI',10)
$brand=New-Object Windows.Forms.Label
$brand.Text='MEFF  M3 PRO'
$brand.Font=New-Object Drawing.Font('Segoe UI',25,[Drawing.FontStyle]::Bold)
$brand.ForeColor=$teal
$brand.SetBounds(28,20,650,48)
$form.Controls.Add($brand)
$subtitle=New-Object Windows.Forms.Label
$subtitle.Text='SETUP WINDOWS  |  VERSIONE UFFICIALE'
$subtitle.ForeColor=$muted
$subtitle.Font=New-Object Drawing.Font('Segoe UI',10,[Drawing.FontStyle]::Bold)
$subtitle.SetBounds(32,74,850,26)
$form.Controls.Add($subtitle)
$stage=New-Object Windows.Forms.Label
$stage.Text='Preparazione della checklist del PC...'
$stage.Font=New-Object Drawing.Font('Segoe UI',12,[Drawing.FontStyle]::Bold)
$stage.SetBounds(32,113,870,32)
$form.Controls.Add($stage)
$list=New-Object Windows.Forms.ListView
$list.SetBounds(32,153,876,265)
$list.View='Details'; $list.FullRowSelect=$true; $list.GridLines=$false
$list.BackColor=$panelColor; $list.ForeColor=[Drawing.Color]::White
$list.BorderStyle='None'; $list.HeaderStyle='Nonclickable'
[void]$list.Columns.Add('COMPONENTE',190)
[void]$list.Columns.Add('STATO',230)
[void]$list.Columns.Add('OPERAZIONE',430)
$form.Controls.Add($list)
$progress=New-Object Windows.Forms.ProgressBar
$progress.SetBounds(32,432,876,7); $progress.Style='Marquee';$progress.MarqueeAnimationSpeed=25
$form.Controls.Add($progress)
$log=New-Object Windows.Forms.RichTextBox
$log.SetBounds(32,454,876,155)
$log.BackColor=[Drawing.ColorTranslator]::FromHtml('#0B1925')
$log.ForeColor=$muted; $log.ReadOnly=$true; $log.BorderStyle='None'
$log.Font=New-Object Drawing.Font('Consolas',9)
$log.Text='Verifica dei prerequisiti e integrita del setup...'
$form.Controls.Add($log)
$install=New-Object Windows.Forms.Button
$install.Text='INSTALLA M3PRO';$install.SetBounds(680,633,228,45)
$install.FlatStyle='Flat';$install.BackColor=$teal;$install.ForeColor=$dark
$install.Font=New-Object Drawing.Font('Segoe UI',11,[Drawing.FontStyle]::Bold)
$install.Enabled=$false
$form.Controls.Add($install)
$check=New-Object Windows.Forms.Button
$check.Text='Ricontrolla PC';$check.SetBounds(32,633,155,45)
$check.FlatStyle='Flat';$check.ForeColor=$muted
$form.Controls.Add($check)
$verify=New-Object Windows.Forms.Button
$verify.Text='Verifica download';$verify.SetBounds(199,633,165,45)
$verify.FlatStyle='Flat';$verify.ForeColor=$muted
$form.Controls.Add($verify)
$note=New-Object Windows.Forms.Label
$note.Text='Licenza e accesso Tailscale si completano dopo il setup. Eventuali driver richiedono conferma.'
$note.Font=New-Object Drawing.Font('Segoe UI',8)
$note.ForeColor=$muted;$note.SetBounds(32,690,876,22)
$form.Controls.Add($note)
function Start-SetupJob([string]$RequestedMode) {
    if ($script:worker -and -not $script:worker.HasExited) { return }
    $script:sequence++;$script:mode=$RequestedMode;$script:lastLog=''
    $script:stdout=Join-Path $jobRoot ("out-$($script:sequence).txt")
    $script:stderr=Join-Path $jobRoot ("err-$($script:sequence).txt")
    $install.Enabled=$false;$check.Enabled=$false;$verify.Enabled=$false
    $progress.Style='Marquee';$progress.MarqueeAnimationSpeed=25
    $stage.Text = switch ($RequestedMode) {'check' {'Controllo dei componenti del PC...'} 'verify' {'Verifica della release ufficiale e del download...'} default {'Installazione M3PRO in corso...'}}
    $stage.ForeColor=[Drawing.Color]::White
    $progress.Value=0
    if ($RequestedMode -eq 'install') {$progress.Style='Blocks';$stage.Text='0% - Preparazione installazione (avanzamento per fasi)'}
    $log.Text='Avvio operazione...'
    $flags = switch ($RequestedMode) {'check' {' -ChecklistOnly'} 'verify' {' -CheckOnly'} default {''}}
    if ($RequestedMode -eq 'install' -and $ResumeIncomplete) {$flags += ' -ResumeIncomplete'}
    try {
        $script:worker=Start-Process -FilePath "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -File "'+$engine+'" -StatusFile "'+$statusFile+'"'+$flags) -WindowStyle Hidden -RedirectStandardOutput $script:stdout -RedirectStandardError $script:stderr -PassThru
        $null=$script:worker.Handle
    } catch {
        $stage.Text='Avvio non riuscito';$log.Text=$_.Exception.Message
        $check.Enabled=$true;$verify.Enabled=$true;$progress.Style='Blocks'
    }
}
function Refresh-SetupView {
    if (Test-Path $statusFile) {
        try {
            $state=Get-Content -LiteralPath $statusFile -Raw | ConvertFrom-Json
            if ($script:mode -eq 'install' -and $null -ne $state.percent) {
                $progress.Style='Blocks';$progress.Value=[Math]::Max(0,[Math]::Min(100,[int]$state.percent))
                $stage.Text=([string]$state.percent + '% - ' + $state.phase)
            }
            $script:transcript=Join-Path $state.log_directory 'installazione.log'
            $list.BeginUpdate();$list.Items.Clear()
            $script:machinePresent=$false
            foreach($row in $state.checklist) {
                $item=New-Object Windows.Forms.ListViewItem([string]$row.Componente)
                [void]$item.SubItems.Add([string]$row.Stato);[void]$item.SubItems.Add([string]$row.Azione)
                if ($row.Stato -eq 'PRESENTE' -or $row.Stato -eq 'OK') {$item.ForeColor=$teal}
                elseif ($row.Stato -eq 'MANCANTE') {$item.ForeColor=[Drawing.Color]::Gold}
                if ($row.Componente -eq 'M3 installato' -and $row.Stato -like 'PRESENTE*') {$script:machinePresent=$true}
                [void]$list.Items.Add($item)
            }
            $list.EndUpdate()
        } catch {}
    }
    $text=''
    foreach($file in @($script:transcript,$script:stdout,$script:stderr)) {
        if($file -and (Test-Path $file)) {try {$stream=[IO.File]::Open($file,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite);$reader=New-Object IO.StreamReader($stream);try {$text += $reader.ReadToEnd()+"`r`n"} finally {$reader.Dispose()}}catch{}}
    }
    if($text -and $text -ne $script:lastLog) {
        $script:lastLog=$text
        $log.Text=$text.Substring([Math]::Max(0,$text.Length-18000))
        $log.SelectionStart=$log.TextLength;$log.ScrollToCaret()

    }
    if($script:worker -and $script:worker.HasExited) {
        $script:worker.WaitForExit();$exitCode=$script:worker.ExitCode;$script:worker.Dispose();$script:worker=$null
        $progress.Style='Blocks'
        $check.Enabled=$true;$verify.Enabled=$true
        $script:readyForInstall=($exitCode -eq 0)
        if($exitCode -ne 0){$stage.Text='Operazione non completata - consulta il dettaglio qui sotto';$stage.ForeColor=[Drawing.Color]::Salmon}
        elseif($script:mode -eq 'install'){$stage.Text='100% - M3PRO avviato - controlla il riepilogo dei componenti';$stage.ForeColor=$teal;$progress.Value=100}
        elseif($script:machinePresent){$stage.Text='M3 gia presente: per aggiornare usa il pulsante Update nell app';$stage.ForeColor=$teal}
        elseif($script:mode -eq 'verify'){$stage.Text='Pacchetto ufficiale verificato. Puoi procedere con il setup.';$stage.ForeColor=$teal}
        else{$stage.Text='Checklist pronta. Installa M3PRO per continuare.';$stage.ForeColor=[Drawing.Color]::White}
        $install.Enabled=($script:readyForInstall -and -not $script:machinePresent -and -not $CheckOnly)
    }
}
$timer=New-Object Windows.Forms.Timer
$timer.Interval=700;$timer.Add_Tick({Refresh-SetupView})
$check.Add_Click({Start-SetupJob 'check'})
$verify.Add_Click({Start-SetupJob 'verify'})
$install.Add_Click({Start-SetupJob 'install'})
$form.Add_FormClosing({param($sender,$e) if($script:worker -and -not $script:worker.HasExited){$e.Cancel=$true;[Windows.Forms.MessageBox]::Show('Operazione in corso. Attendi la conclusione prima di chiudere.','M3PRO Setup') | Out-Null}})
if ($PreviewPath) {
    Start-SetupJob 'check'
    while($script:worker){Start-Sleep -Milliseconds 200;Refresh-SetupView}
    $form.Show();[Windows.Forms.Application]::DoEvents();$form.PerformLayout()
    $bitmap=New-Object Drawing.Bitmap($form.Width,$form.Height)
    $form.DrawToBitmap($bitmap,(New-Object Drawing.Rectangle(0,0,$form.Width,$form.Height)))
    $bitmap.Save($PreviewPath,[Drawing.Imaging.ImageFormat]::Png);$bitmap.Dispose();$form.Dispose()
    Write-Output $PreviewPath
    exit 0
}
$form.Add_Shown({$timer.Start();Start-SetupJob 'check'})
[void]$form.ShowDialog()
$timer.Stop();$timer.Dispose();$form.Dispose()

